#include <algorithm>
#include <cassert>
#include <cmath>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
enum class State { Playing, Paused, Ended };
struct Scene {
    State state=State::Playing;
    double time=0;
    unsigned commits=0;
    void finish() { // 필수 결과는 한 번만 확정한다.
        if(state==State::Ended) return;
        state=State::Ended; time=10; ++commits;
    }
    void pause(){if(state==State::Playing)state=State::Paused;}
    void resume(){if(state==State::Paused)state=State::Playing;}
    void skip(){finish();} // 이 모델에서는 정지 중에도 건너뛸 수 있다.
    void tick(double dt){
        if(!std::isfinite(dt)||dt<0||dt>1)throw std::invalid_argument("dt");
        if(state!=State::Playing)return;
        time=std::min(10.0,time+dt);
        if(time>=10)finish();
    }
};
int main(){
    Scene a; a.tick(1); a.pause(); a.tick(1); assert(a.time==1);
    a.resume();a.tick(1);assert(a.time==2);
    a.pause();a.skip();assert(a.state==State::Ended&&a.commits==1&&a.time==10);
    for(int i=0;i<10000;++i){a.skip();a.resume();a.tick(0.25);}
    assert(a.commits==1&&a.time==10);
    Scene b;for(int i=0;i<40;++i)b.tick(0.25);
    assert(b.state==State::Ended&&b.commits==1);
    bool rejected=false;try{b.tick(-1);}catch(const std::invalid_argument&){rejected=true;}
    assert(rejected);
    std::cout<<"cutscene state tests passed\n";
}
